{"path": "outline.json", "content": "{
  "act_one": {
    "description": "1992年南方小城，刚下岗的苏晓梅被倒爷陈闯雇佣押货去北方，两人踏上七天七夜的南北旅途，初步建立人物关系和故事基调。",
    "key_chapters": [
      {
        "chapter_number": 1,
        "chapter_title": "嘉陵后座的风",
        "core_event": "陈闯找到刚下岗的苏晓梅，出高价雇她跟自己跑一趟北方押货，苏晓梅为了弟弟的学费答应，两人收拾东西开着嘉陵摩托踏上国道，出发第一个县城陈闯就买了一对鸳鸯枕巾。",
        "emotional_tone": "局促、新鲜，带着一丝隐秘的期待",
        "key_scenes": ["纺织厂门口陈闯找苏晓梅", "苏晓梅收拾简单行李", "嘉陵摩托开上国道，风灌进苏晓梅的衣领", "第一家供销社陈闯买枕巾"]
      }
    ],
    "turning_point": "苏晓梅看着陈闯把枕巾塞进边斗，以为他是要囤货倒卖，完全没猜到这是他流浪婚礼的第一份聘礼。"
  },
  "act_two": {
    "description": "旅途中间五天，两人一路向北遭遇各种状况，感情逐渐升温，双向暗恋的张力逐渐拉满，陈闯的流浪婚礼暗线持续推进。",
    "key_chapters": [
      {
        "chapter_number": 2,
        "chapter_title": "枕巾上的鸳鸯",
        "core_event": "接下来四天两人风餐露宿，陈闯每经过一个县城就进供销社买一对鸳鸯枕巾，边斗里的枕巾越堆越高，苏晓梅每次都偷偷在地图上把经过的城市画个心。",
        "emotional_tone": "暧昧拉扯，甜中带涩",
        "key_scenes": ["国道边小饭馆分吃一碗面", "夜宿路边简陋招待所，两人各睡一张床", "遇到联防队查车，陈闯把苏晓梅护在身后", "苏晓梅就着路灯缝补陈闯磨破的外套"]
      },
      {
        "chapter_number": 3,
        "chapter_title": "暴风雨里的红丝巾",
        "core_event": "第五天遭遇特大暴雨，陈闯不顾苏晓梅阻拦，冒雨冲进路边供销社给她买了一条红丝巾挡风，回来之后发烧晕倒，苏晓梅在招待所照顾了他一夜，确认了自己的心意。",
        "emotional_tone": "心疼、感动，情愫彻底爆发",
        "key_scenes": ["暴雨里摩托艰难前行", "陈闯把唯一的雨衣披给苏晓梅", "陈闯冒雨买红丝巾回来浑身湿透", "苏晓梅给陈闯物理降温，偷偷亲了他的额头"]
      }
    ],
    "turning_point": "苏晓梅决定等这趟货跑完，就跟陈闯坦白自己的心意，不管他是不是只是把自己当雇工。"
  },
  "act_three": {
    "description": "最后两天两人到达目的地，生意赔本，陈闯说出流浪婚礼的真相和赌约，最终走向宿命的悲剧结局。",
    "key_chapters": [
      {
        "chapter_number": 4,
        "chapter_title": "一万张婚床",
        "core_event": "两人到达北方批发市场，收货的王老板故意压价，这趟生意赔得血本无归，最后一夜两人在桥洞过夜，陈闯把边斗里所有的枕巾铺在地上当床，说出流浪婚礼的真相和赌约。",
        "emotional_tone": "压抑、酸涩，真相揭开的震撼",
        "key_scenes": ["王老板压价收走货物，陈闯把所有钱都给了苏晓梅", "桥洞下流浪汉老李递来半包火柴", "陈闯铺开几十对枕巾，说这是他们的一万张婚床", "陈闯说出赌约：赚了娶她，赔了他就归摩托"]
      },
      {
        "chapter_number": 5,
        "chapter_title": "结冰的河面",
        "core_event": "苏晓梅半夜醒过来，发现陈闯不见了，只留下边斗里堆得满满的枕巾，还有两张揣在她口袋里的去深圳的车票，远处结冰的河面上传来摩托坠河的闷响，苏晓梅抱着枕巾在河边坐了整整一夜。",
        "emotional_tone": "绝望、悲凉，宿命的破碎感",
        "key_scenes": ["苏晓梅醒过来发现陈闯不在", "摸到口袋里的两张深圳车票", "远处传来摩托坠河的声音", "苏晓梅抱着枕巾在河边坐到天亮", "苏晓梅攥着车票走向火车站"]
      }
    ],
    "turning_point": "陈闯赌输了，他遵守诺言把摩托归了苏晓梅，自己归了摩托，把活下去的机会留给了她。"
  }
}"}

